import glob
import os
import re
import sys

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

# Plots the worker/core sweep (06_cores/<system>/results, generated by make_core_yamls.py) into 06_cores/<system>/results/plots:
#   <system>_scaling_<size>_<direction>.png   GB/s over the worker count, fixed (block) vs dynamic chunk distribution, M = 2 and 4,
#                                             median with min-max band; host kernel and the sweep base so far for comparison
#   <system>_<group>_<app>_<direction>_M<m>.png   GB/s over the data size, one line per configuration (outliers visible as bands)
# Usage: python 06_cores/plot_cores.py <system> [<system> ...]

HERE = os.path.dirname(os.path.abspath(__file__))
FAR = {"gpuc4": "E-cores", "ifi": "other L3 group", "lumi": "NUMA node 3"}
DIRECTIONS = {"copy_bandwidth": "host to device (first access)", "d2h_gbps": "device to host"}
ORDER_STYLE = {"block": dict(color="tab:blue"), "dynamic": dict(color="tab:orange")}
M_STYLE = {2: dict(linestyle="-", marker="o"), 4: dict(linestyle="--", marker="s")}
CAPTION = ("each worker on its own core (nearest free cores first, never Celerity's CPUs 1-4 or hyper-threading siblings); 4 MiB chunks, "
           "staging = workers x 4 MiB;\nfixed = COPYLIB_PLAN_ORDER=block (worker i takes the i-th block of chunks), dynamic = each "
           "worker takes the next chunk nobody has started; celerity-bench 014e21a")


def label(system, cfg):
    if cfg == "reference_base":
        return "base so far (2 workers, fixed, 16 MiB chunks)"
    if cfg == "reference_host_kernel":
        return "host kernel"
    m = re.match(r"workers_(\d+)(?:_(\w+))?$", cfg)
    if m:
        n = int(m.group(1))
        return f"{n} worker" + ("s" if n > 1 else "") + (f", {'fixed' if m.group(2) == 'block' else 'dynamic'}" if m.group(2) else "")
    m = re.match(r"place_(\w+)_(block|dynamic)$", cfg)
    where = {"far": f"4 far ({FAR[system]})", "mixed": f"2 near + 2 far ({FAR[system]})", "all": "4, WORKER_CPUS=all"}[m.group(1)]
    return f"{where}, {'fixed' if m.group(2) == 'block' else 'dynamic'}"


def load(system):
    frames = []
    for f in glob.glob(os.path.join(HERE, system, "results", "*.csv")):
        d = pd.read_csv(f)
        d["cfg"] = os.path.basename(f)[:-4]
        frames.append(d)
    d = pd.concat(frames, ignore_index=True)
    bad = d[d.check != "ok"]
    if len(bad):
        print(f"WARNING {system}: {len(bad)} rows without 'Check: ok':")
        print(bad.groupby(["cfg", "application"]).size().to_string())
    d = d[d.check == "ok"].copy()
    d["workers"] = d.cfg.str.extract(r"workers_(\d+)")[0].astype(float)
    d["order"] = np.where(d.cfg.str.endswith("dynamic"), "dynamic", "block")
    d["mib"] = d.N * 4 / 2 ** 20
    return d


def scaling(system, d, out):
    w = d[d.workers.notna()]
    if w.empty:
        return
    counts = sorted(w.workers.unique())
    apps = sorted(d.application.unique())
    for n in (2 ** 28, 2 ** 26):
        for metric, what in DIRECTIONS.items():
            fig, axes = plt.subplots(1, len(apps), figsize=(16, 7), sharey=True)
            for ax, app in zip(np.atleast_1d(axes), apps):
                for m in (2, 4):
                    for order in ("block", "dynamic"):
                        # one worker: a single run, shown on both lines
                        x = w[(w.application == app) & (w.N == n) & (w.M == m) & ((w.order == order) | (w.workers == 1))]
                        g = x.groupby("workers")[metric].agg(["median", "min", "max"]).reindex(counts)
                        ax.plot(g.index, g["median"], label=f"M={m}, {'fixed' if order == 'block' else 'dynamic'}",
                                **ORDER_STYLE[order], **M_STYLE[m])
                        ax.fill_between(g.index, g["min"], g["max"], alpha=0.15, color=ORDER_STYLE[order]["color"])
                    for cfg, style in (("reference_host_kernel", dict(color="gray")), ("reference_base", dict(color="black"))):
                        r = d[(d.cfg == cfg) & (d.application == app) & (d.N == n) & (d.M == m)][metric].median()
                        if np.isnan(r):
                            continue
                        if cfg == "reference_host_kernel":
                            ax.axhline(r, linestyle=M_STYLE[m]["linestyle"], linewidth=1.5, label=f"M={m}, host kernel", **style)
                        else:
                            ax.plot([2], [r], marker="x" if m == 2 else "+", markersize=12, linestyle="none",
                                    label=f"M={m}, base so far", **style)
                ax.set_xscale("log", base=2)
                ax.set_xticks(counts)
                ax.set_xticklabels([str(int(c)) for c in counts])
                ax.set_xlabel("workers (each on its own core)")
                ax.set_title(app)
                ax.grid(True, which="both", alpha=0.5)
            np.atleast_1d(axes)[0].set_ylabel("bandwidth in GB/s")
            np.atleast_1d(axes)[0].legend(fontsize=8, loc="best")
            fig.suptitle(f"{system}: {what}, {n * 4 // 2 ** 20} MiB per copy (median, band = min-max of 3 runs)")
            fig.text(0.01, 0.01, CAPTION, fontsize=8, va="bottom")
            fig.tight_layout(rect=(0, 0.06, 1, 1))
            path = os.path.join(out, f"{system}_scaling_{n * 4 // 2 ** 20}MiB_{metric}.png")
            fig.savefig(path, dpi=200)
            plt.close(fig)
            print(path)


def by_size(system, d, out):
    refs = ["reference_base", "reference_host_kernel"]
    groups = {
        "workers_fixed": refs + sorted(c for c in d.cfg.unique() if c.startswith("workers_") and not c.endswith("dynamic")),
        "workers_dynamic": refs + ["workers_01"] + sorted(c for c in d.cfg.unique() if c.endswith("dynamic") and c.startswith("workers_")),
        "placement": refs + ["workers_04_block", "workers_04_dynamic"] + sorted(c for c in d.cfg.unique() if c.startswith("place_")),
    }
    for group, cfgs in groups.items():
        cfgs = [c for c in cfgs if c in set(d.cfg)]
        if not cfgs:
            continue
        others = [c for c in cfgs if c not in refs]
        cmap = plt.get_cmap("viridis" if group != "placement" else "tab10")
        colors = {c: cmap(i / max(1, len(others) - 1) * 0.9) if group != "placement" else cmap(i) for i, c in enumerate(others)}
        colors.update({"reference_base": "black", "reference_host_kernel": "gray"})
        for app in sorted(d.application.unique()):
            for metric, what in DIRECTIONS.items():
                for m in (2, 4):
                    fig, ax = plt.subplots(figsize=(16, 9))
                    for c in cfgs:
                        x = d[(d.cfg == c) & (d.application == app) & (d.M == m)]
                        g = x.groupby("mib")[metric].agg(["median", "min", "max"])
                        ref = c in refs
                        style = "--" if "dynamic" in c else "-"
                        ax.plot(g.index, g["median"], marker="o", markersize=4, linewidth=2.5 if ref else 1.5, color=colors[c],
                                linestyle=":" if ref else style, label=label(system, c))
                        ax.fill_between(g.index, g["min"], g["max"], alpha=0.1, color=colors[c])
                    ax.set_xscale("log", base=2)
                    ax.set_yscale("log")
                    sizes = sorted(d.mib.unique())
                    ax.set_xticks(sizes)
                    ax.set_xticklabels([f"{s * 1024:g} KiB" if s < 1 else f"{s:g} MiB" if s < 1024 else f"{s / 1024:g} GiB" for s in sizes])
                    ax.set_xlabel("data size per copy")
                    ax.set_ylabel("bandwidth in GB/s")
                    ax.grid(True, which="both", alpha=0.5)
                    ax.legend(fontsize=8, ncol=2)
                    ax.set_title(f"{system} {group}, M={m}, {what}, {app}")
                    fig.text(0.01, 0.01, CAPTION, fontsize=8, va="bottom")
                    fig.tight_layout(rect=(0, 0.05, 1, 1))
                    path = os.path.join(out, f"{system}_{group}_{app}_{metric}_M{m}.png")
                    fig.savefig(path, dpi=200)
                    plt.close(fig)
                    print(path)


def main():
    for system in sys.argv[1:]:
        d = load(system)
        out = os.path.join(HERE, system, "results", "plots")
        os.makedirs(out, exist_ok=True)
        scaling(system, d, out)
        by_size(system, d, out)


if __name__ == "__main__":
    main()
